ALTER TABLE "products" ADD COLUMN "list_price_vnd" bigint;--> statement-breakpoint
ALTER TABLE "products" ADD COLUMN "overview" text;--> statement-breakpoint
ALTER TABLE "products" ADD COLUMN "highlights" jsonb DEFAULT '[]'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "products" ADD COLUMN "specifications" jsonb DEFAULT '[]'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "products" ADD COLUMN "package_contents" jsonb DEFAULT '[]'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "products" ADD COLUMN "warranty_months" integer;--> statement-breakpoint
ALTER TABLE "products" ADD CONSTRAINT "products_list_price_check" CHECK ("products"."list_price_vnd" is null or "products"."list_price_vnd" between "products"."price_vnd" + 1 and 9999999999);--> statement-breakpoint
ALTER TABLE "products" ADD CONSTRAINT "products_warranty_check" CHECK ("products"."warranty_months" is null or "products"."warranty_months" between 1 and 120);--> statement-breakpoint
-- Product detail content for the demo catalog: match exact SKU and product name.
-- Reference prices and short specs come from the former storefront listing.
-- Warranty stays NULL unless the manufacturer term is known for that product.
WITH detail (sku, expected_name, list_price_vnd, overview, highlights, specifications, package_contents, warranty_months) AS (
	VALUES
		('DEMO-IPHONE-15-128', 'iPhone 15 128GB', 19990000::bigint, 'iPhone 15 có màn hình OLED 6,1 inch với Dynamic Island, mặt lưng kính nhám và khung nhôm, chuẩn kháng nước IP68. Camera chính 48 MP, chip A16 Bionic và cổng USB-C đáp ứng tốt nhu cầu chụp ảnh, làm việc và giải trí hằng ngày.', '["Màn hình OLED 6,1 inch với Dynamic Island","Camera chính 48 MP","Chip A16 Bionic, RAM 6 GB","Cổng USB-C, hỗ trợ sạc không dây","Kháng nước và bụi chuẩn IP68"]'::jsonb, '[{"title":"Màn hình","rows":[{"label":"Kích thước","value":"6,1 inch"},{"label":"Công nghệ","value":"Super Retina XDR OLED"},{"label":"Độ phân giải","value":"2556 x 1179 pixel"},{"label":"Tần số quét","value":"60 Hz"}]},{"title":"Hiệu năng","rows":[{"label":"Chip","value":"Apple A16 Bionic"},{"label":"RAM","value":"6 GB"},{"label":"Bộ nhớ trong","value":"128 GB"},{"label":"Hệ điều hành khi ra mắt","value":"iOS 17"}]},{"title":"Camera","rows":[{"label":"Camera sau","value":"48 MP (chính), 12 MP (góc siêu rộng)"},{"label":"Camera trước","value":"12 MP"}]},{"title":"Pin và kết nối","rows":[{"label":"Dung lượng pin","value":"3.349 mAh"},{"label":"Cổng sạc","value":"USB-C"},{"label":"Mạng di động","value":"5G"},{"label":"SIM","value":"Nano SIM và eSIM"},{"label":"NFC","value":"Có"}]},{"title":"Thiết kế","rows":[{"label":"Kích thước","value":"147,6 x 71,6 x 7,8 mm"},{"label":"Khối lượng","value":"171 g"},{"label":"Kháng nước, bụi","value":"IP68"},{"label":"Chất liệu","value":"Khung nhôm, mặt lưng kính"}]}]'::jsonb, '["iPhone 15 128GB","Cáp sạc USB-C","Que chọc SIM","Sách hướng dẫn"]'::jsonb, 12::integer),
		('DEMO-LOGITECH-G304', 'Chuột gaming Logitech G304', 890000::bigint, 'Logitech G304 là chuột gaming không dây dùng kết nối LIGHTSPEED và cảm biến HERO, độ phân giải tối đa 12.000 DPI. Chuột nặng 99 g, dùng một pin AA với thời lượng tới 250 giờ tùy cách sử dụng.', '["Không dây LIGHTSPEED qua đầu thu USB","Cảm biến HERO, tối đa 12.000 DPI","Thời lượng pin tới 250 giờ với 1 pin AA","Nhẹ 99 g, tốc độ phản hồi 1 ms"]'::jsonb, '[{"title":"Cảm biến","rows":[{"label":"Loại cảm biến","value":"HERO"},{"label":"Độ phân giải","value":"200 - 12.000 DPI"},{"label":"Tốc độ theo dõi","value":"Trên 400 IPS"},{"label":"Gia tốc","value":"Trên 40 G"}]},{"title":"Kết nối","rows":[{"label":"Kết nối","value":"Không dây LIGHTSPEED, đầu thu USB"},{"label":"Tốc độ phản hồi","value":"1 ms"}]},{"title":"Pin và thiết kế","rows":[{"label":"Pin","value":"1 pin AA"},{"label":"Thời lượng pin","value":"Tới 250 giờ, tùy cách sử dụng"},{"label":"Khối lượng","value":"99 g"}]}]'::jsonb, '["Chuột Logitech G304","Đầu thu USB LIGHTSPEED","1 pin AA","Tài liệu hướng dẫn"]'::jsonb, NULL::integer),
		('DEMO-ASUS-VIVOBOOK-14', 'Laptop ASUS Vivobook 14', 21990000::bigint, 'Laptop ASUS Vivobook 14 dùng vi xử lý Intel Core i5, RAM 16 GB và SSD 512 GB, phù hợp cho học tập, văn phòng và các tác vụ hằng ngày.', '["Vi xử lý Intel Core i5","RAM 16 GB","SSD 512 GB","Màn hình 14 inch"]'::jsonb, '[{"title":"Cấu hình","rows":[{"label":"Vi xử lý","value":"Intel Core i5"},{"label":"RAM","value":"16 GB"},{"label":"Ổ cứng","value":"SSD 512 GB"},{"label":"Kích thước màn hình","value":"14 inch"}]}]'::jsonb, '[]'::jsonb, 24::integer),
		('DEMO-LAPTOP-SLIM-14', 'Laptop mỏng nhẹ 14 inch', 24990000::bigint, 'Laptop mỏng nhẹ màn hình 14 inch, cấu hình Intel Core i5, RAM 16 GB và SSD 512 GB, phù hợp cho nhu cầu di chuyển, học tập và làm việc.', '["Thiết kế mỏng nhẹ","Vi xử lý Intel Core i5","RAM 16 GB","SSD 512 GB"]'::jsonb, '[{"title":"Cấu hình","rows":[{"label":"Vi xử lý","value":"Intel Core i5"},{"label":"RAM","value":"16 GB"},{"label":"Ổ cứng","value":"SSD 512 GB"},{"label":"Kích thước màn hình","value":"14 inch"}]}]'::jsonb, '[]'::jsonb, NULL::integer),
		('DEMO-PC-GAMING', 'PC gaming cấu hình mạnh', 36990000::bigint, 'PC gaming với vi xử lý Intel Core i7, card đồ họa RTX và RAM 32 GB, phù hợp để chơi game và xử lý các tác vụ nặng.', '["Vi xử lý Intel Core i7","Card đồ họa RTX","RAM 32 GB"]'::jsonb, '[{"title":"Cấu hình","rows":[{"label":"Vi xử lý","value":"Intel Core i7"},{"label":"Card đồ họa","value":"RTX"},{"label":"RAM","value":"32 GB"}]}]'::jsonb, '[]'::jsonb, NULL::integer),
		('DEMO-LG-27-2K', 'Màn hình LG 27 inch 2K', 7990000::bigint, 'Màn hình LG 27 inch độ phân giải 2K, tấm nền IPS, tần số quét 144 Hz và hỗ trợ HDR10, phù hợp cho cả làm việc và giải trí.', '["Màn hình 27 inch, độ phân giải 2K","Tấm nền IPS","Tần số quét 144 Hz","Hỗ trợ HDR10"]'::jsonb, '[{"title":"Màn hình","rows":[{"label":"Kích thước","value":"27 inch"},{"label":"Độ phân giải","value":"2K"},{"label":"Tấm nền","value":"IPS"},{"label":"Tần số quét","value":"144 Hz"},{"label":"HDR","value":"HDR10"}]}]'::jsonb, '[]'::jsonb, NULL::integer),
		('DEMO-HEADPHONES-WIRELESS', 'Tai nghe không dây', 1790000::bigint, 'Tai nghe không dây có chống ồn và thời lượng pin 30 giờ, phù hợp để nghe nhạc, học tập và làm việc.', '["Kết nối không dây","Chống ồn","Pin 30 giờ"]'::jsonb, '[{"title":"Thông số chính","rows":[{"label":"Kết nối","value":"Không dây"},{"label":"Chống ồn","value":"Có"},{"label":"Thời lượng pin","value":"30 giờ"}]}]'::jsonb, '[]'::jsonb, NULL::integer),
		('DEMO-KEYBOARD-RGB', 'Bàn phím cơ RGB', 1290000::bigint, 'Bàn phím cơ có đèn nền RGB, kết nối USB, phù hợp cho cả làm việc và chơi game.', '["Switch cơ","Đèn nền RGB","Kết nối USB"]'::jsonb, '[{"title":"Thông số chính","rows":[{"label":"Loại switch","value":"Switch cơ"},{"label":"Đèn nền","value":"RGB"},{"label":"Kết nối","value":"USB"}]}]'::jsonb, '[]'::jsonb, NULL::integer)
)
UPDATE "products" AS p
SET "list_price_vnd" = CASE WHEN detail.list_price_vnd > p."price_vnd" THEN detail.list_price_vnd END,
	"overview" = detail.overview,
	"highlights" = detail.highlights,
	"specifications" = detail.specifications,
	"package_contents" = detail.package_contents,
	"warranty_months" = detail.warranty_months,
	"version" = p."version" + 1,
	"updated_at" = CURRENT_TIMESTAMP
FROM detail
WHERE p."sku" = detail.sku
	AND p."name" = detail.expected_name;
